using System.Collections.Generic; using System.Globalization; using System.Text; namespace MyLumo { public static class CommandPlanner { public static List<LumoTask> Plan(string c){var t=new List<LumoTask>();string s=N(c);if(Has(s,"sapka","kalap","hat","cap","palaria","oltozz","dress"))t.Add(new(LumoActionType.Dress,LumoLocation.Wardrobe,Has(s,"piros","red","rosu")?"red_cap":"cap","wardrobe",c));if(Has(s,"pizza","egyél","egyel","eat","mananca"))t.Add(new(LumoActionType.Eat,Has(s,"varos","city","oras")?LumoLocation.PizzaShop:LumoLocation.Kitchen,"pizza","pizza",c));if(Has(s,"tanc","dance","danseaza"))t.Add(new(LumoActionType.Dance,LumoLocation.LivingRoom,"","dance_spot",c));if(Has(s,"gitar","guitar","chitara"))t.Add(new(LumoActionType.PlayGuitar,LumoLocation.LivingRoom,"guitar","guitar_spot",c));if(Has(s,"alud","sleep","dormi"))t.Add(new(LumoActionType.Sleep,LumoLocation.Bedroom,"","bed",c));if(Has(s,"kutya","dog","caine","baratkozz","friend"))t.Add(new(LumoActionType.PetAnimal,LumoLocation.Yard,"","dog",c));if(Has(s,"auto","car","masina"))t.Add(new(LumoActionType.EnterCar,LumoLocation.Yard,"car","car",c));if(Has(s,"tenger","beach","plaja"))t.Add(new(LumoActionType.Move,LumoLocation.Beach,"","beach_entry",c));else if(Has(s,"hegy","mountain","munte"))t.Add(new(LumoActionType.Move,LumoLocation.Mountains,"","mountain_entry",c));else if(Has(s,"varos","city","oras"))t.Add(new(LumoActionType.Move,LumoLocation.City,"","city_entry",c));else if(Has(s,"haza","otthon","home","acasa"))t.Add(new(LumoActionType.Move,LumoLocation.Home,"","home_entry",c));if(t.Count==0)t.Add(new(LumoActionType.Idle,LumoLocation.Home,"","",c));return t;} static bool Has(string s,params string[] v){foreach(var x in v)if(s.Contains(N(x)))return true;return false;} static string N(string v){if(string.IsNullOrWhiteSpace(v))return"";var d=v.ToLowerInvariant().Normalize(NormalizationForm.FormD);var b=new StringBuilder();foreach(char c in d)if(CharUnicodeInfo.GetUnicodeCategory(c)!=UnicodeCategory.NonSpacingMark)b.Append(c);return b.ToString().Normalize(NormalizationForm.FormC);} } }
